import{_ as a,o as e,c as r,a2 as t}from"./chunks/framework.EUByU7Iq.js";const _=JSON.parse('{"title":"《佛经 · 心经》","description":"","frontmatter":{"title":"《佛经 · 心经》","date":"2026-11-22T00:00:00.000Z","categories":["美文","佛经"],"collection":"《佛经 · 心经》","tags":["佛经","唐"],"poem":true,"poem_quote":false,"merged":true,"pieces":1,"author":"玄奘 译","source_book":"佛经"},"headers":[],"relativePath":"blogs/佛经·心经/index.md","filePath":"blogs/佛经·心经/index.md"}'),p={name:"blogs/佛经·心经/index.md"};function i(o,s,l,c,d,u){return e(),r("div",null,[...s[0]||(s[0]=[t('<h1 id="《佛经-·-心经》" tabindex="-1">《佛经 · 心经》 <a class="header-anchor" href="#《佛经-·-心经》" aria-label="Permalink to &quot;《佛经 · 心经》&quot;">​</a></h1><p class="poem-meta">唐 · 玄奘 译</p><p>全文 7 段，经文与白话逐段对照，收录完整。</p><div class="merged-book"><h3 id="般若波罗蜜多心经" tabindex="-1">般若波罗蜜多心经 <a class="header-anchor" href="#般若波罗蜜多心经" aria-label="Permalink to &quot;般若波罗蜜多心经&quot;">​</a></h3><div class="sutra"><div class="su-pair"><p class="su-org">观自在菩萨，行深般若波罗蜜多时，照见五蕴皆空，度一切苦厄。</p><p class="su-tra">观自在菩萨在深修般若智慧的时候，照见色、受、想、行、识这五蕴全是空的，于是越出了一切的苦与灾厄。</p></div><div class="su-pair"><p class="su-org">“舍利子！色不异空，空不异色，色即是空，空即是色；受、想、行、识，亦复如是。”</p><p class="su-tra">“舍利子啊！有形的一切并不离开空，空也不离开有形的一切；色当体就是空，空当体就是色。受、想、行、识，也同样是这样的。”</p></div><div class="su-pair"><p class="su-org">“舍利子！是诸法空相，不生不灭，不垢不净，不增不减。是故，空中无色，无受、想、行、识；无眼、耳、鼻、舌、身、意；无色、声、香、味、触、法；无眼界，乃至无意识界；无无明，亦无无明尽，乃至无老死，亦无老死尽；无苦、集、灭、道；无智，亦无得，以无所得故。”</p><p class="su-tra">“舍利子啊！这一切法都是空的相状：不曾生起，也不曾灭去；不曾污秽，也不曾洁净；不曾增加，也不曾减少。所以在这空里，没有色，没有受、想、行、识；没有眼、耳、鼻、舌、身、意；没有色、声、香、味、触、法；从眼界一直到意识界，都没有；没有无明，也没有‘无明灭尽’，乃至没有老死，也没有‘老死灭尽’；没有苦、集、灭、道这四谛；没有能证的智，也没有所得的果。正因为一丝一毫都无所得。”</p></div><div class="su-pair"><p class="su-org">“菩提萨埵，依般若波罗蜜多故，心无罣碍；无罣碍故，无有恐怖，远离颠倒梦想，究竟涅槃。三世诸佛，依般若波罗蜜多故，得阿耨多罗三藐三菩提。”</p><p class="su-tra">“菩萨依靠这般若波罗蜜多，心里没有挂碍；因为没有挂碍，也就没有恐怖，能远离颠倒的念头和梦幻般的执着，直走到究竟的涅槃。三世的佛，也都是依靠这般若波罗蜜多，才证得无上正等正觉的。”</p></div><div class="su-pair"><p class="su-org">“故知般若波罗蜜多，是大神咒，是大明咒，是无上咒，是无等等咒，能除一切苦，真实不虚。”</p><p class="su-tra">“所以要知道：这般若波罗蜜多，是大神咒，是大明咒，是无上咒，是没有哪个能与它相等的咒，能除去一切的苦——真实，不虚。”</p></div><div class="su-pair"><p class="su-org">故说般若波罗蜜多咒，即说咒曰：</p><p class="su-tra">因此说这般若波罗蜜多的咒，也就是接着念道：</p></div><div class="su-pair"><p class="su-org">“揭谛 揭谛 波罗揭谛 波罗僧揭谛 菩提萨婆诃”</p><p class="su-tra">“去吧，去吧，到彼岸去，大家都到彼岸去，觉悟而圆满。”（这一句是梵语的音译，意思是这样。）</p></div></div></div>',4)])])}const v=a(p,[["render",i]]);export{_ as __pageData,v as default};
